   330	 * type-agnostic. The target `entityType` still governs CREATE-on-miss.
   331	 */
   332	async function lookupMatches(
   333	  sql: DbClient,
   334	  params: {
   335	    orgId: string;
   336	    identities: ExtractedLink['identities'][];
   337	  }
   338	): Promise<Map<string, number>> {
   339	  const keys = new Set<string>();
   340	  for (const arr of params.identities) {
   341	    for (const id of arr) keys.add(`${id.namespace}\u0000${id.identifier}`);
   342	  }
   343	  if (keys.size === 0) return new Map();
   344	
   345	  const namespaces: string[] = [];
   346	  const identifiers: string[] = [];
   347	  for (const key of keys) {
   348	    const [ns, ident] = key.split('\u0000');
   349	    namespaces.push(ns);
   350	    identifiers.push(ident);
   351	  }
   352	
   353	  const rows = await sql<{ entity_id: number | string; namespace: string; identifier: string }>`
   354	    SELECT ei.entity_id, ei.namespace, ei.identifier
   355	    FROM entity_identities ei
   356	    JOIN entities e ON e.id = ei.entity_id
   357	    WHERE ei.organization_id = ${params.orgId}
   358	      AND ei.deleted_at IS NULL
   359	      AND e.deleted_at IS NULL
   360	      AND (ei.namespace, ei.identifier) IN (
   361	        SELECT ns, ident FROM unnest(${pgTextArray(namespaces)}::text[], ${pgTextArray(identifiers)}::text[]) AS u(ns, ident)
   362	      )
   363	  `;
   364	
   365	  const out = new Map<string, number>();
