   372	/**
   373	 * Resolve a link's identities onto at most one entity, honouring identity tiers.
   374	 *
   375	 * A present `primary` identity (immutable, e.g. `github_user_id`) is
   376	 * authoritative: it governs even when it matches nothing (a new account), so a
   377	 * stale non-primary like a reused `github_login` can't merge a fresh account
   378	 * into the old person. Without a primary, identities match equal-weight (the
   379	 * cross-channel behavior whatsapp/email rely on).
   380	 *
   381	 * This is the single definition of that rule. It is deliberately shared by both
   382	 * resolution sites: the ordinary lookup AND the orphan-recovery re-resolution
   383	 * after a lost auto-create race. Those two used to carry separate copies and the
   384	 * recovery copy was tier-blind, which mis-resolved whenever a primary's owner
   385	 * was soft-deleted while a live entity held a recycled secondary claim — the
   386	 * link landed on the recycled-claim holder. `member_of` is a read ACL, so that
   387	 * handed one person another person's channel access.
   388	 *
   389	 * Returns the entity id when exactly one candidate survives, `null` when
   390	 * nothing matched at the governing tier, and `'ambiguous'` when several
   391	 * entities tied there — callers must fail closed on `'ambiguous'` and never
   392	 * pick one.
   393	 */
   394	function resolveIdentityTier(
   395	  identities: ResolvedIdentity[],
   396	  matches: Map<string, number>
   397	): number | null | 'ambiguous' {
   398	  const primaries = identities.filter((i) => i.primary);
   399	  // A present primary governs alone; otherwise every identity votes equally.
   400	  const governing = primaries.length > 0 ? primaries : identities;
   401	  const hits = new Set<number>();
   402	  for (const id of governing) {
   403	    const h = matches.get(`${id.namespace}\u0000${id.identifier}`);
   404	    if (h !== undefined) hits.add(h);
   405	  }
   406	  if (hits.size > 1) return 'ambiguous';
   407	  if (hits.size === 1) return [...hits][0];
   408	  return null;
   409	}
