   585	  const preferNonEmpty: Record<string, unknown> = {};
   586	  for (const [key, value] of params.traits) {
   587	    const spec = params.rule.traits[key];
   588	    if (!spec || spec.behavior === 'init_only') continue;
   589	    if (value === undefined) continue;
   590	    if (spec.behavior === 'overwrite') {
   591	      overwrite[key] = value;
   592	    } else if (spec.behavior === 'prefer_non_empty') {
   593	      const empty = value === null || value === '';
   594	      if (!empty) preferNonEmpty[key] = value;
   595	    }
   596	  }
   597	  if (Object.keys(overwrite).length === 0 && Object.keys(preferNonEmpty).length === 0) return;
   598	
   599	  // Read-modify-write the metadata jsonb. A single worker processes a given
   600	  // (connector, run) batch sequentially, so intra-batch races are impossible;
   601	  // cross-batch races touching the same entity are rare enough to accept
   602	  // last-writer-wins.
   603	  const rows = await sql<{ metadata: Record<string, unknown> | null }>`
   604	    SELECT metadata
   605	    FROM entities
   606	    WHERE id = ${params.entityId}
   607	      AND organization_id = ${params.orgId}
   608	      AND deleted_at IS NULL
   609	    LIMIT 1
   610	  `;
   611	  if (rows.length === 0) return;
   612	  const current = rows[0].metadata ?? {};
   613	
   614	  const next: Record<string, unknown> = { ...current, ...overwrite };
   615	  for (const [key, value] of Object.entries(preferNonEmpty)) {
   616	    const existing = current[key];
   617	    if (existing === undefined || existing === null || existing === '') {
   618	      next[key] = value;
   619	    }
   620	  }
   621	
   622	  await sql`
   623	    UPDATE entities
   624	    SET metadata = ${sql.json(next)},
   625	        updated_at = current_timestamp
   626	    WHERE id = ${params.entityId}
   627	      AND organization_id = ${params.orgId}
   628	      AND deleted_at IS NULL
   629	  `;
   630	}
