     1	/**
     2	 * Entity-link SQL helpers: event-recall identity namespaces,
     3	 * entityLinkMatchSql, EntityIdentityScope, fetchEntityIdentityScopes,
     4	 * buildEntityLinkUnion.
     5	 */
     6	
     7	import { EVENT_RECALL_IDENTITY_NAMESPACES } from '@lobu/connector-sdk/identity-namespaces';
     8	import { type DbClient, pgTextArray } from '../../db/client';
     9	import { CONNECTOR_RECALL_NAMESPACES } from '../../identity/connector-identity-modules';
    10	
    11	/**
    12	 * Identity namespaces backed by partial BTREE indexes on `events.metadata`.
    13	 *
    14	 * The canonical registry lives in connector-sdk so connectors, the identity
    15	 * engine, and read-time recall share one vocabulary. This server-side export
    16	 * assembles the registry used by event-attribution recall and its index invariant.
    17	 *
    18	 * Non-recall namespaces are intentionally unsupported here: without a matching
    19	 * index the identity branch seq-scans `events`, which blows up the entire
    20	 * content query. If a connector needs a new recall namespace, declare it in the
    21	 * connector's identity module (`recallNamespaces`) and add the matching
    22	 * `idx_events_metadata_<ns>` migration — a startup/CI invariant asserts the two
    23	 * stay in sync.
    24	 *
    25	 * The generic recall namespaces come from connector-sdk; the connector-specific
    26	 * ones are contributed by each connector module and assembled server-side.
    27	 */
    28	export const STANDARD_IDENTITY_NAMESPACES: readonly string[] = [
    29	  ...EVENT_RECALL_IDENTITY_NAMESPACES,
    30	  ...CONNECTOR_RECALL_NAMESPACES,
    31	];
    32	
    33	/**
    34	 * SQL predicate: "event `<alias>` is linked to entity `<paramRef>`".
    35	 *
    36	 * Matches two ways:
    37	 *   1. Legacy / feed-pinned attribution: entity id appears in `events.entity_ids`.
    38	 *   2. Identity-graph attribution: a live `entity_identities` row claims an
    39	 *      identifier that the event carries in `metadata->>namespace` (stamped
    40	 *      there by `applyEventAttributions` at ingestion; see src/utils/entity-link-upsert.ts).
    41	 *
    42	 * Events are append-only, so (2) is how connector-driven auto-linking is
    43	 * surfaced at read time — `entity_ids` is never mutated post-insert.
    44	 *
    45	 * Shape: `alias.id IN (UNION …)`. Each standard namespace gets its own UNION
    46	 * branch with a literal `ei.namespace = '<ns>'` so Postgres can evaluate the
    47	 * join against `entity_identities` first, then probe `events` via the
    48	 * per-namespace partial BTREE index `idx_events_metadata_<ns>`. Writing this
    49	 * as a top-level OR of EXISTS branches — or as a single identity branch with
    50	 * `OR` across namespaces — forces Parallel Seq Scan on `events` because the
    51	 * namespace becomes a join filter instead of a restrictable predicate.
    52	 */
    53	export function entityLinkMatchSql(paramRef: string, alias = 'f'): string {
    54	  // Direct (feed-pinned / save_content / webhook) attribution: the entity id is
    55	  // stamped in `events.entity_ids`. Merge redirect: also match events stamped
    56	  // with any entity MERGED INTO this one — a merged loser's raw-stamped events
    57	  // (which can't be rewritten, events being append-only) recall against the
    58	  // winner. `applyMerge` FLATTENS chains (L→W→V is stored as L→V, W→V), so a
    59	  // single `merged_into = X` hop reaches every descendant loser — no recursion.
    60	  // `&&` (overlap) against the {self ∪ direct losers} set; the losers subquery
    61	  // is one indexed lookup (idx_entities_merged_into), a one-time InitPlan even
    62	  // when `paramRef` is an outer column, NOT per-event (see
    63	  // entity-merge-redirect-plan.test.ts).
    64	  const directBranch = `SELECT e2.id FROM events e2
    65	      WHERE e2.entity_ids && ARRAY(
    66	        SELECT en.id FROM entities en
    67	        WHERE en.id = ${paramRef} OR en.merged_into = ${paramRef}
    68	      )`;
    69	
    70	  const standardBranches = STANDARD_IDENTITY_NAMESPACES.map(
    71	    (ns) => `SELECT e2.id FROM events e2
    72	      JOIN entity_identities ei
    73	        ON ei.entity_id = ${paramRef}
    74	       AND ei.namespace = '${ns}'
    75	       AND ei.deleted_at IS NULL
    76	      WHERE e2.metadata ? '${ns}' AND e2.metadata->>'${ns}' = ei.identifier`
    77	  );
    78	
    79	  const branches = [directBranch, ...standardBranches].join('\n    UNION\n    ');
    80	  return `${alias}.id IN (\n    ${branches}\n  )`;
    81	}
    82	
    83	/**
    84	 * One identity claim for an entity — `(namespace, identifier)`.
    85	 *
    86	 * Used by `fetchEntityIdentityScopes` + `buildEntityLinkUnion` to skip the
    87	 * UNION branches that would never match for this entity. On a 4.7GB events
    88	 * table the empty-branches-still-cost-real-time issue is the difference
    89	 * between 200ms and 1.2s on the candidate_set scan alone.
    90	 */
    91	export interface EntityIdentityScope {
    92	  namespace: string;
    93	  identifier: string;
    94	}
    95	
    96	/**
    97	 * Pre-fetch the live `entity_identities` rows for one entity, restricted to
    98	 * the namespaces we have backing indexes for (`STANDARD_IDENTITY_NAMESPACES`).
    99	 *
   100	 * Cheap: indexed scan via `idx_entity_identities_by_entity`. Typical entity
   101	 * has 0-3 rows. Run once per request, not per query.
   102	 */
   103	export async function fetchEntityIdentityScopes(
   104	  sql: DbClient,
   105	  entityId: number
   106	): Promise<EntityIdentityScope[]> {
   107	  const rows = (await sql`
   108	    SELECT namespace, identifier
   109	    FROM entity_identities
   110	    WHERE entity_id = ${entityId}
   111	      AND deleted_at IS NULL
   112	      AND namespace = ANY(${pgTextArray([...STANDARD_IDENTITY_NAMESPACES])}::text[])
   113	  `) as Array<{ namespace: unknown; identifier: unknown }>;
   114	  return rows.map((r) => ({
   115	    namespace: String(r.namespace),
   116	    identifier: String(r.identifier),
   117	  }));
   118	}
   119	
   120	/**
   121	 * Build the same `<alias>.id IN (UNION …)` predicate as `entityLinkMatchSql`,
   122	 * but emit only the branches an entity actually needs.
   123	 *
   124	 * Differences from the legacy helper:
   125	 *  - The direct `entity_ids @> ARRAY[N]` branch is always included.
   126	 *  - One `metadata->>'<ns>' = $N` branch per pre-fetched scope (no JOIN to
   127	 *    `entity_identities`; the identifier is bound as a parameter). For an
   128	 *    entity with no identities, that's zero extra branches — Postgres only
   129	 *    plans the direct scan.
   130	 *  - Uses an inline `entityIdLiteral` (already validated as a numeric id) so
   131	 *    the planner sees the actual id and picks the entity-specific GIN scan
   132	 *    instead of building a generic plan.
   133	 *
   134	 * Identifier values are bound params (caller appends them to its params
   135	 * array), defending against tampering even though `entity_identities` is
   136	 * write-controlled.
   137	 */
   138	export function buildEntityLinkUnion(opts: {
   139	  /** Already-validated entity id, will be inlined as `<id>::bigint`. */
   140	  entityIdLiteral: number;
   141	  scopes: EntityIdentityScope[];
   142	  alias?: string;
   143	  baseParamIndex: number;
   144	}): { sql: string; params: string[] } {
   145	  const alias = opts.alias ?? 'f';
   146	  // Merge redirect (see entityLinkMatchSql): match events stamped with this
   147	  // entity OR any entity merged into it, so a merged loser's raw-stamped events
   148	  // recall against the winner. Chains are flattened at merge time (merged_into is
   149	  // the flattened root), so one indexed hop reaches every descendant loser.
   150	  const direct = `SELECT e2.id FROM events e2
   151	      WHERE e2.entity_ids && ARRAY(
   152	        SELECT en.id FROM entities en
   153	        WHERE en.id = ${opts.entityIdLiteral}::bigint OR en.merged_into = ${opts.entityIdLiteral}::bigint
   154	      )`;
   155	  const params: string[] = [];
   156	  let paramIndex = opts.baseParamIndex;
   157	
   158	  // Skip namespaces we have no backing index for (e.g. anything outside
   159	  // STANDARD_IDENTITY_NAMESPACES) — they'd seq-scan events. The fetch helper
   160	  // already filters to the standard list, but we double-check here so a
   161	  // future caller that builds scopes manually can't blow up the scan.
   162	  const indexed = new Set<string>(STANDARD_IDENTITY_NAMESPACES);
   163	  const scopeBranches: string[] = [];
   164	  for (const scope of opts.scopes) {
   165	    if (!indexed.has(scope.namespace)) continue;
   166	    params.push(scope.identifier);
   167	    scopeBranches.push(
   168	      `SELECT e2.id FROM events e2 WHERE e2.metadata ? '${scope.namespace}' AND e2.metadata->>'${scope.namespace}' = $${paramIndex}`
   169	    );
   170	    paramIndex += 1;
   171	  }
   172	
   173	  const branches = [direct, ...scopeBranches].join('\n    UNION\n    ');
   174	  return {
   175	    sql: `${alias}.id IN (\n    ${branches}\n  )`,
   176	    params,
   177	  };
   178	}
