   178	 */
   179	async function resolveMembers(
   180	  orgId: string,
   181	  connectorKey: string,
   182	  connectionId: number | null,
   183	  members: AccessMember[],
   184	  memberIdentities: AccessIdentitySpec[],
   185	): Promise<Map<string, number>> {
   186	  const byKey = new Map<string, number>();
   187	  if (members.length === 0) return byKey;
