   189	  // Gather identity values per namespace and look up existing owners (any type).
   190	  const valuesByNamespace = new Map<string, Set<string>>();
   191	  for (const m of members) {
   192	    for (const id of m.identities) {
   193	      if (!id.value) continue;
   194	      const set = valuesByNamespace.get(id.namespace) ?? new Set<string>();
