   210	    // entity-link-upsert already joins for this reason; this matcher did not.
   211	    const rows = await sql<{ identifier: string; entity_id: number }>`
   212				SELECT ei.identifier, ei.entity_id
   213				FROM entity_identities ei
   214				JOIN entities e ON e.id = ei.entity_id
   215				WHERE ei.organization_id = ${orgId}
   216				  AND ei.namespace = ${namespace}
   217				  AND ei.identifier = ANY(${pgTextArray(list)}::text[])
