   256	    }
   257	    let hit: number | undefined;
   258	    if (primaryPresent) {
   259	      if (primaryHits.size === 1) {
   260	        hit = [...primaryHits][0];
   261	        const overridden = [...secondaryHits].filter((id) => id !== hit);
   262	        if (overridden.length > 0) {
