437							runId: batch.run_id,
438							parentOriginId: item.origin_parent_id,
439						},
440						{
441							onConflictUpdate: true,
442							// Dry path only: the tx that gets rolled back — the INSERT
443							// genuinely executes, so every constraint, trigger and NOT NULL
444							// is exercised for real. The real path must NOT pass `db` even
445							// though it equals the singleton: a caller-supplied `sql` makes
446							// insertEvent skip its advisory-lock dedup transaction (the
447							// caller's tx is assumed to be the atomic scope), and that lock
448							// is what serializes concurrent ingests of the same
449							// (connection_id, origin_id) across replicas.
450							sql: isDry ? db : undefined,
451							afterPersist: async (persisted, tx) => {
452								const drafts = item.behavior_signals ?? [];
453								if (drafts.length > 0) {
454									for (const [draftIndex, draft] of drafts.entries()) {
455										const signal = materializeConnectorBehaviorSignal({
456											draft,
457											change: persisted.change,
458											connectorKey: run.connector_key,
459											connectionId: run.connection_id,
460											deliveryId: `sync:${batch.run_id}:event:${persisted.id}:${draftIndex}`,
461										});
462										if (!signal) continue;
463										activations.push(
464											...(await activateBehaviorSignal({
465												organizationId: run.organization_id,
466												signal,
467												db: tx,
468											}))
469										);
470									}
471								} else if (deriveContext) {
472									const derived = deriveConnectorActivationSignals(
473										deriveContext,
474										{
475											connectionId: run.connection_id,
476											originId: item.id,
477											kind: itemOriginType ?? itemSemanticType,
478											title: item.title ?? null,
479											payloadText: item.payload_text ?? null,
480											sourceUrl: item.source_url ?? null,
481											occurredAt: item.occurred_at ?? new Date(),
482											metadata:
483												item.metadata as Record<string, unknown> | undefined,
484										},
485										persisted.change,
486										persisted.id,
487									);
488									for (const signal of derived) {
489										activations.push(
490											...(await activateBehaviorSignal({
491												organizationId: run.organization_id,
492												signal,
493												db: tx,
494											}))
495										);
496									}
497								}
498							},
499						}
500					);
501					// ESCAPES THE TX: this dispatches real Behavior runs to the worker
502					// fleet. The activation ROWS roll back with the tx, but a dispatched
503					// agent run has already left the database — it would run against, and
504					// react to, an event that is about to cease to exist.
505					if (!isDry) {
506						await dispatchBehaviorRunsBestEffort(activations);
507					}
508					if (inserted) {
509						totalItems++;
510						// ESCAPES THE TX: detached (`.catch(() => {})`) and writes through
511						// the getDb() singleton, not `db`, so its writes would commit
512						// independently of the rollback — and race it, since nothing awaits
513						// them.
514						if (entityIds.length > 0 && !isDry) {
515							autoLinkEvent({
516								eventId: Number(inserted.id),
517								entityIds,
518								content: item.payload_text,
519								title: item.title,
520								organizationId: run.organization_id,
521							}).catch(() => {});
522						}
523						// Captured after a successful insert, so the preview describes rows
524						// that really did land (and would land again on a real sync) rather
525						// than rows we merely hoped would.
526						if (isDry && dryPreview.length < DRY_RUN_PREVIEW_LIMIT) {
527							dryPreview.push({
528								origin_id: item.id,
529								title: item.title,
530								semantic_type: itemSemanticType,
531								payload_type: item.payload_type,
532								occurred_at: item.occurred_at,
533								author_name: item.author_name,
534								source_url: item.source_url,
535								// Bounded: a preview is for eyeballing shape, and some
536								// connectors emit very large bodies.
537								content_preview:
538									typeof item.payload_text === "string"
539										? item.payload_text.slice(0, DRY_RUN_CONTENT_CHARS)
540										: null,
541								attachment_count: item.attachments?.length ?? 0,
542							});
543						}
544					}
545				} catch (err) {
546					console.error("[stream] Insert failed for item", item.id, ":", err);
547					throw err;
548				}
549			}
550	
551				// ESCAPES THE TX: transcription is an external, paid API call, and it
552				// is fired detached so nothing awaits it. `pendingTranscriptions` is
553				// already empty on a dry run (nothing was materialized above), but the
