297	export async function upsertConnectorDefinitionRecords(params: {
298	  sql: SqlClient;
299	  organizationId: string;
300	  metadata: ConnectorMetadata;
301	  versionRecord: ConnectorVersionPersistence;
302	  /**
303	   * Which connector_versions namespace the version row belongs to.
304	   *
305	   * - 'shared': a pointer at bundled on-disk source (source_path, no code) —
306	   *   identical for every org, deduped on one organization_id-IS-NULL row.
307	   * - 'organization': org-supplied bytes (install_connector / source_url /
308	   *   source_code / mcp_url) land ONLY on the caller org's own
309	   *   (organization_id, connector_key, version) row — never the shared
310	   *   namespace (#2045: a shared row of custom code is a cross-org
311	   *   read/activate surface). Content-empty records (rollback and mcp_url
312	   *   upserts pass all-NULL and rely on COALESCE keeping stored code) never
313	   *   overwrite anything; they create a marker org row only when NO row
314	   *   exists for the pair at all (first mcp_url install) — a rollback target
315	   *   always exists, and an empty org row must never shadow a code-bearing
316	   *   shared row.
317	   */
318	  versionScope: 'shared' | 'organization';
319	}): Promise<{ updated: boolean }> {
320	  const { sql } = params;
321	  const { metadata } = params;
322	
323	  const authSchemaJson = metadata.authSchema ? sql.json(metadata.authSchema) : null;
324	  const feedsSchemaJson = metadata.feeds ? sql.json(metadata.feeds) : null;
325	  const actionsSchemaJson = metadata.actions ? sql.json(metadata.actions) : null;
326	  const behaviorEventsJson = metadata.behaviorEvents ? sql.json(metadata.behaviorEvents) : null;
327	  const optionsSchemaJson = metadata.optionsSchema ? sql.json(metadata.optionsSchema) : null;
328	  const mcpConfigJson = metadata.mcpConfig ? sql.json(metadata.mcpConfig) : null;
329	  const openapiConfigJson = metadata.openapiConfig ? sql.json(metadata.openapiConfig) : null;
330	  const runtimeJson = metadata.runtime ? sql.json(metadata.runtime) : null;
331	  const agentToolingJson = metadata.agentTooling ? sql.json(metadata.agentTooling) : null;
332	  // Capability flag (#2033 item 2): readiness reads this instead of assuming a
333	  // declared action is executable. Older metadata (no field) stays NULL =
334	  // "assume supported" so nothing regresses.
335	  const supportsExecute = metadata.supportsExecute ?? null;
336	
337	  const existing = await sql`
338	    SELECT id, status, login_enabled
339	    FROM connector_definitions
340	    WHERE key = ${metadata.key}
341	      AND organization_id = ${params.organizationId}
342	    ORDER BY
343	      CASE WHEN status = 'active' THEN 0 ELSE 1 END,
344	      updated_at DESC,
345	      id DESC
346	    LIMIT 1
347	  `;
348	
349	  const existingRow = existing[0] as
350	    | { id: number; status: string; login_enabled: boolean }
351	    | undefined;
352	  const preservedLoginEnabled = existingRow?.login_enabled ?? false;
353	
354	  let wasActive = existingRow?.status === 'active';
355	
356	  if (existingRow?.status === 'active') {
357	    await sql`
358	      UPDATE connector_definitions
359	      SET name = ${metadata.name},
360	          description = ${metadata.description ?? null},
361	          version = ${metadata.version},
362	          auth_schema = ${authSchemaJson},
363	          feeds_schema = ${feedsSchemaJson},
364	          actions_schema = ${actionsSchemaJson},
365	          behavior_events = ${behaviorEventsJson},
366	          options_schema = ${optionsSchemaJson},
367	          mcp_config = ${mcpConfigJson},
368	          openapi_config = ${openapiConfigJson},
369	          favicon_domain = ${metadata.faviconDomain ?? null},
370	          required_capability = ${metadata.requiredCapability ?? null},
371	          runtime = ${runtimeJson},
372	          agent_tooling = ${agentToolingJson},
373	          supports_execute = ${supportsExecute},
374	          login_enabled = ${preservedLoginEnabled},
375	          updated_at = NOW()
376	      WHERE id = ${existingRow.id}
377	    `;
378	    // Fall through to the shared connector_versions upsert below.
379	  } else {
380	    // No active row seen — but the SELECT is not a lock, so a concurrent
381	    // installer may INSERT the active row between our SELECT and INSERT. ON
382	    // CONFLICT DO NOTHING makes the loser a no-op (returns no row) WITHOUT
383	    // aborting an enclosing transaction — critical because a caller
384	    // (device-reconcile) passes a `tx`, where a raw 23505 would poison the whole
385	    // transaction (25P02).
386	    const inserted = await sql`
387	      INSERT INTO connector_definitions (
388	        organization_id, key, name, description, version,
389	        auth_schema, feeds_schema, actions_schema, behavior_events, options_schema,
390	        mcp_config, openapi_config, favicon_domain, required_capability,
391	        runtime, agent_tooling, supports_execute, status, login_enabled
392	      ) VALUES (
393	        ${params.organizationId}, ${metadata.key}, ${metadata.name},
394	        ${metadata.description ?? null}, ${metadata.version},
395	        ${authSchemaJson}, ${feedsSchemaJson}, ${actionsSchemaJson}, ${behaviorEventsJson},
396	        ${optionsSchemaJson},
397	        ${mcpConfigJson}, ${openapiConfigJson},
398	        ${metadata.faviconDomain ?? null}, ${metadata.requiredCapability ?? null},
399	        ${runtimeJson}, ${agentToolingJson}, ${supportsExecute}, 'active', ${preservedLoginEnabled}
400	      )
401	      ON CONFLICT (organization_id, key)
402	        WHERE organization_id IS NOT NULL AND status = 'active'
403	        DO NOTHING
404	      RETURNING id
405	    `;
406	
407	    if (inserted.length === 0) {
408	      // The race loser: the winner already created the active row. Update it so
409	      // both callers converge on this install's metadata (last-write-wins,
410	      // matching the sequential UPDATE branch above).
411	      wasActive = true;
