180	export async function extractConnectorMetadata(compiledCode: string): Promise<ConnectorMetadata> {
181	  return extractMetadata<ConnectorMetadata>(compiledCode, {
182	    tmpPrefix: '.connector-meta-',
183	    runnerCode: CONNECTOR_RUNNER_CODE,
184	  });
185	}
186	
187	/**
188	 * Assert that extracted connector metadata carries the required identity
189	 * fields. Throws with the canonical message used across the install paths.
190	 */
191	export function validateConnectorMetadata(metadata: ConnectorMetadata): void {
192	  if (!metadata.key || !metadata.name || !metadata.version) {
193	    throw new Error('Connector must have key, name, and version.');
194	  }
195	  // The web app routes `/connectors/<key>/<connectionId>` against a catch-all
196	  // param, and static sibling segments (CONNECTOR_SUBROUTE_SEGMENTS) win the
197	  // match. A connector installed under one of those names would have every
198	  // connection page it owns shadowed by an unrelated route — reject the
199	  // install rather than ship a connector whose pages are unreachable.
200	  if (isReservedConnectorKey(metadata.key)) {
201	    throw new Error(
202	      `Connector key '${metadata.key}' is reserved by a /connectors/ route. Pick another key.`
203	    );
204	  }
205	}

