260	  origin_type?: string;        // Source-native type (must match a key in eventKinds)
261	  payload_text: string;        // Main text content
262	  title?: string;              // Title / subject
263	  author_name?: string;        // Author
264	  source_url?: string;         // Link to original
265	  occurred_at: Date;           // When the content was created
266	  semantic_type?: string;      // Semantic type (e.g. 'content', 'note', 'summary', 'fact')
267	  score?: number;              // Engagement score (0-100)
268	  origin_parent_id?: string;   // Parent reference for threaded content
269	  metadata?: Record<string, unknown>; // Matches the eventKind's metadataSchema
270	  embedding?: number[];        // Pre-computed embedding vector (optional)
